def render_downloads():
    names={'PapersMinimal':'Complete manuscript archive','ProofChainAudits':'Full proof-chain records','DAGAtlas':'Canonical graph and current source overlays','S3StructureNetwork':'Exact finite geometry network'}
    def cell(a):
        label=next((t for k,t in names.items() if k in a['name']),a['version'])
        return (f'<article class="download-panel"><span class="kicker">{E(a["version"])}</span><h3>{E(label)}</h3>'
                f'<p>{a["bytes"]/(1024*1024):.1f} MiB · Original archive supplied by the framework project. SHA-256 below verifies the exact bundle.</p>'
                f'<p class="id-string mono-break"><code>{E(a["sha256"])}</code></p><a class="btn btn-secondary" href="{E(a["sitePath"])}" download>Download ZIP ↓</a></article>')
    main=page_hero('Reproducible source archives','The actual files','Download the exact current source, audits, dependency atlas and geometry network. The paper PDF and TeX files can also be read individually on this website.')
    main+=f'<div class="container page-section"><div class="download-grid">{"".join(cell(x) for x in MANIFEST["archives"])}</div><div class="notice" style="margin-top:32px"><strong>What is and is not checked.</strong> Site validation checks that the current source/PDF hashes agree with the published inventory and that archive SHA-256 values match these files. That does not independently prove every theorem, physical occurrence or measurement comparison. <a href="verification.html">Read the audit record →</a></div><div class="actions"><a class="btn btn-secondary" href="papers.html">Read individual papers →</a><a class="btn btn-secondary" href="research.html">Browse labels and obligations →</a></div></div>'
    (DOC/'downloads.html').write_text(shell('Downloads',main,'research','Current original versioned scientific archives with SHA-256 provenance.'),encoding='utf-8')

